INSERT INTO auth.users VALUES ('11111111-1111-4111-8111-111111111111','one@example.invalid',now()),('22222222-2222-4222-8222-222222222222','two@example.invalid',now()),('33333333-3333-4333-8333-333333333333','review@example.invalid',now());
INSERT INTO public.admin_users(id,role) VALUES('33333333-3333-4333-8333-333333333333','kyc_reviewer');
SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
SET ROLE authenticated;
DO $$ BEGIN
 BEGIN UPDATE public.profiles SET identity_verified=true; RAISE EXCEPTION 'profile update allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN INSERT INTO public.profiles(id) VALUES('22222222-2222-4222-8222-222222222222'); RAISE EXCEPTION 'profile insert allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN INSERT INTO public.orders(user_id) VALUES('11111111-1111-4111-8111-111111111111'); RAISE EXCEPTION 'order insert allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN INSERT INTO public.order_items(order_id,card_name,grade) VALUES(gen_random_uuid(),'fake','PSA10'); RAISE EXCEPTION 'item insert allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN INSERT INTO storage.objects(bucket_id,name) VALUES('identity-images','11111111-1111-4111-8111-111111111111/fake.jpg'); RAISE EXCEPTION 'storage insert allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.consume_security_rate_limit(repeat('a',64),2,60000); RAISE EXCEPTION 'RPC public'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 IF (SELECT count(*) FROM public.profiles) <> 1 THEN RAISE EXCEPTION 'profile isolation failed'; END IF;
END $$;
RESET ROLE;
SET ROLE service_role;
DO $$ DECLARE r jsonb; doc uuid; order_data jsonb; item uuid; n integer; BEGIN
 r:=public.consume_security_rate_limit(repeat('a',64),2,60000);
 IF NOT (r->>'allowed')::boolean THEN RAISE EXCEPTION 'rate first'; END IF;
 PERFORM public.consume_security_rate_limit(repeat('a',64),2,60000);
 r:=public.consume_security_rate_limit(repeat('a',64),2,60000);
 IF (r->>'allowed')::boolean THEN RAISE EXCEPTION 'rate third'; END IF;
 INSERT INTO public.identity_cleanup_jobs(user_id,storage_path) VALUES('11111111-1111-4111-8111-111111111111','11111111-1111-4111-8111-111111111111/new.jpg');
 PERFORM public.commit_identity_document('11111111-1111-4111-8111-111111111111','11111111-1111-4111-8111-111111111111/new.jpg','license',NULL);
 SELECT id INTO doc FROM public.identity_documents WHERE user_id='11111111-1111-4111-8111-111111111111';
 PERFORM public.review_identity_document('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',true);
 UPDATE public.profiles SET address='changed' WHERE id='11111111-1111-4111-8111-111111111111';
 IF (SELECT identity_verified FROM public.profiles WHERE id='11111111-1111-4111-8111-111111111111') THEN RAISE EXCEPTION 'approval survived'; END IF;
 order_data:=public.create_order_secure('{"user_id":"11111111-1111-4111-8111-111111111111","order_number":"AUDIT-1","total_amount":100,"coupon_amount":0}', '[{"item_type":"card","card_name":"test","grade":"PSA10","quantity":1,"unit_price":100}]');
 SELECT id INTO item FROM public.order_items WHERE order_id=(order_data->>'id')::uuid;
 PERFORM public.transition_order_secure((order_data->>'id')::uuid,'unhandled','inspecting','33333333-3333-4333-8333-333333333333',NULL);
 PERFORM public.save_assessment_secure((order_data->>'id')::uuid,'33333333-3333-4333-8333-333333333333','inspecting',jsonb_build_array(jsonb_build_object('itemId',item,'assessedUnitPrice',200)),'[]');
 PERFORM public.decide_order_secure((order_data->>'id')::uuid,'11111111-1111-4111-8111-111111111111',jsonb_build_array(jsonb_build_object('itemId',item,'decision','approved')));
 IF (SELECT total_amount FROM public.orders WHERE id=(order_data->>'id')::uuid) <> 200 THEN RAISE EXCEPTION 'assessment total'; END IF;
 BEGIN PERFORM public.transition_order_secure((order_data->>'id')::uuid,'unhandled','cancelled','11111111-1111-4111-8111-111111111111',NULL); RAISE EXCEPTION 'stale write accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'Order changed' THEN RAISE; END IF; END;
 BEGIN PERFORM public.create_order_secure('{"user_id":"11111111-1111-4111-8111-111111111111","order_number":"AUDIT-BAD","total_amount":100,"coupon_amount":0}', '[{"item_type":"card","card_name":"test","grade":"PSA10","quantity":0,"unit_price":100}]'); EXCEPTION WHEN raise_exception THEN NULL; END;
 IF EXISTS(SELECT 1 FROM public.orders WHERE order_number='AUDIT-BAD') THEN RAISE EXCEPTION 'partial order persisted'; END IF;
 PERFORM public.begin_identity_deletion(doc,'33333333-3333-4333-8333-333333333333');
 IF (SELECT deleted_at FROM public.identity_documents WHERE id=doc) IS NOT NULL THEN RAISE EXCEPTION 'deleted before storage'; END IF;
 PERFORM public.finish_identity_deletion(doc,'33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111/new.jpg');
 PERFORM public.finish_identity_deletion(doc,'33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111/new.jpg');
 SELECT count(*) INTO n FROM public.identity_document_access_logs WHERE document_id=doc AND action='delete';
 IF n<>1 THEN RAISE EXCEPTION 'delete not idempotent'; END IF;
 IF (SELECT id_image_url FROM public.profiles WHERE id='11111111-1111-4111-8111-111111111111') IS NOT NULL THEN RAISE EXCEPTION 'profile not cleared'; END IF;
END $$;
RESET ROLE;
